import { readFile, writeFile } from 'node:fs/promises';

function replaceOnce(source, oldText, newText, label) {
  const count = source.split(oldText).length - 1;
  if (count !== 1) throw new Error(`${label}: expected 1 match, found ${count}`);
  return source.replace(oldText, newText);
}

// ---------- Admin: remove JSON editing from wheel/campaign/task UX ----------
let admin = await readFile('website/digirupee-admin.html', 'utf8');

admin = replaceOnce(admin,
  '.check{display:flex;align-items:center;gap:8px;padding:10px 0;color:#d8d1e7}.check input{accent-color:var(--purple)}',
  `.check{display:flex;align-items:center;gap:8px;padding:10px 0;color:#d8d1e7}.check input{accent-color:var(--purple)}
    .quick-switch{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:14px;border:1px solid var(--line);border-radius:12px;background:#100c1f;margin-bottom:12px}.quick-switch strong{display:block}.quick-switch small{display:block;color:var(--muted);margin-top:3px}.switch{position:relative;width:52px;height:29px;flex:none}.switch input{position:absolute;opacity:0}.switch span{position:absolute;inset:0;border-radius:999px;background:#383247;transition:.18s}.switch span:after{content:'';position:absolute;width:23px;height:23px;left:3px;top:3px;border-radius:50%;background:#fff;transition:.18s}.switch input:checked+span{background:#6f50dc}.switch input:checked+span:after{transform:translateX(23px)}
    .wheel-segment-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;margin:12px 0}.wheel-segment{padding:11px;border:1px solid #2a2443;border-radius:11px;background:#100c1f}.wheel-segment-head{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:8px}.wheel-segment-head strong{font-size:12px}.wheel-segment-fields{display:grid;grid-template-columns:1fr .72fr;gap:7px}.wheel-segment .field{margin:5px 0}.wheel-segment .field label{font-size:9px}.wheel-help{color:var(--muted);font-size:11px;line-height:1.5;margin:8px 0 0}.simple-condition{display:grid;grid-template-columns:1.3fr .7fr;gap:8px}.simple-condition .field{margin:6px 0}@media(max-width:760px){.wheel-segment-grid{grid-template-columns:1fr}.simple-condition{grid-template-columns:1fr}}`,
  'admin helper CSS');

const oldWheelForm = `<form id="wheelForm"><label class="check"><input id="wheelEnabled" type="checkbox"> Wheel enabled</label><div class="field"><label>Daily claim limit</label><input class="input" id="wheelLimit" type="number" min="1" max="10" required></div><div class="field"><label>8 wheel sectors JSON (must contain exactly 8 segments)</label><textarea class="textarea" id="wheelSegments" style="min-height:220px" placeholder='[{"id":"bonus","label":"Bonus","rewardAmount":"1","probabilityWeight":1,"enabled":true}]'></textarea></div><button class="btn primary" id="wheelButton" type="submit">Save wheel</button></form>`;
const newWheelForm = `<form id="wheelForm"><div class="quick-switch"><div><strong>Daily Wheel</strong><small id="wheelToggleState">Turn the wheel on or off instantly.</small></div><label class="switch" aria-label="Wheel enabled"><input id="wheelEnabled" type="checkbox"><span></span></label></div><div class="field"><label>Spins allowed per user each day</label><input class="input" id="wheelLimit" type="number" min="1" max="10" value="1" required></div><div class="panel-heading" style="margin:15px 0 6px"><h3>Wheel prizes</h3><span>No JSON required</span></div><div class="wheel-help">Set reward amount and chance weight for each of the 8 sectors. Higher weight means that sector is selected more often.</div><div class="wheel-segment-grid" id="wheelSegmentsGrid"></div><div class="modal-footer"><button class="btn ghost" id="wheelEqualWeights" type="button">Equal weights</button><button class="btn primary" id="wheelButton" type="submit">Save prizes</button></div></form>`;
admin = replaceOnce(admin, oldWheelForm, newWheelForm, 'wheel form');

admin = replaceOnce(admin,
  `<div class="field"><label>Eligibility JSON</label><textarea class="textarea" id="campaignEligibility" placeholder='{"minimumCompletedUsdt":"1000"}'>{}</textarea></div>`,
  `<div class="notice">No JSON needed. Create the campaign here, then use <b>Add task</b> to choose the bonus condition and reward in a simple form.</div>`,
  'campaign JSON field');

const renderWheelStart = admin.indexOf('      function renderWheel() {');
const renderWheelEnd = admin.indexOf('      function formatRewardMicros', renderWheelStart);
if (renderWheelStart < 0 || renderWheelEnd < 0) throw new Error('renderWheel block not found');
const renderWheelReplacement = `      function defaultWheelSegments() { return Array.from({ length:8 }, (_,index) => ({ id:\`sector_\${index+1}\`, label:\`Prize \${index+1}\`, rewardAmount:'0', probabilityWeight:1, enabled:true })); }
      function normalizedWheelSegments(config) { const source = Array.isArray(config?.segments) && config.segments.length === 8 ? config.segments : defaultWheelSegments(); return source.map((item,index) => ({ id:String(item.id || \`sector_\${index+1}\`), label:String(item.label || \`Prize \${index+1}\`), rewardAmount:String(item.rewardAmount ?? formatRewardMicros(item.rewardAmountMicros)), probabilityWeight:Number.isFinite(Number(item.probabilityWeight)) ? Number(item.probabilityWeight) : 1, enabled:item.enabled !== false })); }
      function wheelSegmentsFromEditor() { return Array.from(document.querySelectorAll('[data-wheel-segment]')).map((row,index) => ({ id:row.dataset.segmentId || \`sector_\${index+1}\`, label:row.querySelector('[data-wheel-label]').value.trim() || \`Prize \${index+1}\`, rewardAmount:row.querySelector('[data-wheel-reward]').value || '0', probabilityWeight:Math.max(0,Math.round(Number(row.querySelector('[data-wheel-weight]').value || 0))), enabled:row.querySelector('[data-wheel-enabled]').checked })); }
      function renderWheel() { if ($('wheelForm')?.dataset.dirty === '1') return; const config = state.wheel || { enabled:false, dailyClaimLimit:1, segments:[] }; const segments = normalizedWheelSegments(config); $('wheelEnabled').checked = !!config.enabled; $('wheelToggleState').textContent = config.enabled ? 'Wheel is live for eligible users.' : 'Wheel is currently off.'; $('wheelLimit').value = config.dailyClaimLimit || 1; $('wheelSegmentsGrid').innerHTML = segments.map((item,index) => \`<div class="wheel-segment" data-wheel-segment data-segment-id="\${esc(item.id)}"><div class="wheel-segment-head"><strong>Sector \${index+1}</strong><label class="check" style="padding:0"><input type="checkbox" data-wheel-enabled \${item.enabled ? 'checked' : ''}> Active</label></div><div class="field"><label>Label</label><input class="input" data-wheel-label maxlength="80" value="\${esc(item.label)}"></div><div class="wheel-segment-fields"><div class="field"><label>Reward USDT</label><input class="input" data-wheel-reward type="number" min="0" step="0.000001" value="\${esc(item.rewardAmount)}"></div><div class="field"><label>Chance weight</label><input class="input" data-wheel-weight type="number" min="0" step="1" value="\${esc(item.probabilityWeight)}"></div></div></div>\`).join(''); $('wheelStats').textContent = \`\${state.wheelHistory.length} recent spins\`; $('wheelBody').innerHTML = state.wheelHistory.length ? state.wheelHistory.map(item => \`<tr><td>\${esc(item.user?.name || item.user?.id || '—')}</td><td>\${esc(item.label)}</td><td>\${amount(item.rewardAmount)}</td><td>\${esc(when(item.createdAt))}</td></tr>\`).join('') : \`<tr><td colspan="4">\${empty('No wheel claims')}</td></tr>\`; }
`;
admin = admin.slice(0, renderWheelStart) + renderWheelReplacement + admin.slice(renderWheelEnd);

const createCampaignStart = admin.indexOf('      async function createCampaign(event) {');
const createCampaignEnd = admin.indexOf('      function addTaskForm', createCampaignStart);
if (createCampaignStart < 0 || createCampaignEnd < 0) throw new Error('createCampaign block not found');
admin = admin.slice(0, createCampaignStart) + `      async function createCampaign(event) { event.preventDefault(); const button = $('campaignButton'); button.disabled = true; try { await api('/admin/campaigns', { method:'POST', body:JSON.stringify({ title:$('campaignTitle').value.trim(), description:$('campaignDescription').value.trim(), type:$('campaignType').value, rewardAmount:$('campaignReward').value, startsAt:campaignDate($('campaignStarts').value), endsAt:campaignDate($('campaignEnds').value), maxClaims:$('campaignMaxClaims').value || null, eligibility:{} }) }); toast('Campaign created. Add a task to choose the bonus condition.'); $('campaignForm').reset(); await refreshAll(); } catch (error) { toast(error.message, true); } finally { button.disabled = false; } }
` + admin.slice(createCampaignEnd);

const addTaskStart = admin.indexOf('      function addTaskForm(campaignId) {');
const addTaskEnd = admin.indexOf('      async function taskDecision', addTaskStart);
if (addTaskStart < 0 || addTaskEnd < 0) throw new Error('addTaskForm block not found');
const addTaskReplacement = `      function taskRequirementPayload() { const type = $('taskRequirementType')?.value || 'firstCompletedOrder'; const raw = $('taskRequirementValue')?.value || ''; if (type === 'firstCompletedOrder') return { firstCompletedOrder:true }; if (type === 'completedOrders') return { completedOrders:Math.max(1,Math.round(Number(raw || 1))) }; if (type === 'minimumCompletedUsdt') return { minimumCompletedUsdt:String(Math.max(0,Number(raw || 0))) }; if (type === 'minimumOrderUsdt') return { minimumOrderUsdt:String(Math.max(0,Number(raw || 0))) }; return {}; }
      function syncTaskRequirementField() { const type = $('taskRequirementType')?.value || 'firstCompletedOrder'; const needsValue = ['completedOrders','minimumCompletedUsdt','minimumOrderUsdt'].includes(type); const wrap = $('taskRequirementValueWrap'); if (wrap) wrap.classList.toggle('hidden', !needsValue); const input = $('taskRequirementValue'); if (input) { input.required = needsValue; input.step = type === 'completedOrders' ? '1' : '0.000001'; input.min = type === 'completedOrders' ? '1' : '0'; input.placeholder = type === 'completedOrders' ? 'e.g. 3' : 'e.g. 1000'; } }
      function addTaskForm(campaignId) { openModal(\`<div class="modal-header"><div><h2>Add bonus task</h2><p>\${esc(campaignId)}</p></div><button class="close" data-action="close-modal">\${icon('path d="M6 6l12 12M18 6 6 18"')}</button></div><form id="taskForm"><div class="field"><label>Task title</label><input class="input" id="taskTitle" maxlength="120" required></div><div class="field"><label>Description</label><textarea class="textarea" id="taskDescription" maxlength="500"></textarea></div><div class="form-grid"><div class="field"><label>Reward USDT</label><input class="input" id="taskReward" type="number" min="0" step="0.000001" required></div><div class="field"><label>How reward is claimed</label><select class="select" id="taskClaimType"><option value="AUTO">Automatic when condition is met</option><option value="MANUAL">Admin approval</option></select></div><div class="field"><label>Claims per user</label><input class="input" id="taskMaxClaims" type="number" min="1" max="100" value="1" required></div></div><div class="panel-heading" style="margin:12px 0 3px"><h3>Bonus condition</h3><span>No JSON required</span></div><div class="simple-condition"><div class="field"><label>Condition</label><select class="select" id="taskRequirementType"><option value="firstCompletedOrder">First completed sell order</option><option value="completedOrders">Completed orders count</option><option value="minimumCompletedUsdt">Total completed USDT volume</option><option value="minimumOrderUsdt">Minimum single order USDT</option><option value="none">No automatic condition</option></select></div><div class="field hidden" id="taskRequirementValueWrap"><label>Target</label><input class="input" id="taskRequirementValue" type="number"></div></div><div class="notice">For manual approval tasks, choose <b>Admin approval</b>. For automatic bonuses, choose a condition above.</div><div class="modal-footer"><button class="btn ghost" type="button" data-action="close-modal">Cancel</button><button class="btn primary" id="taskButton" type="submit">Add bonus task</button></div></form></div>\`); $('taskRequirementType').addEventListener('change', syncTaskRequirementField); syncTaskRequirementField(); $('taskForm').addEventListener('submit', async event => { event.preventDefault(); $('taskButton').disabled = true; try { await api(\`/admin/campaigns/\${encodeURIComponent(campaignId)}/tasks\`, { method:'POST', body:JSON.stringify({title:$('taskTitle').value.trim(),description:$('taskDescription').value.trim(),rewardAmount:$('taskReward').value,claimType:$('taskClaimType').value,maxClaimsPerUser:Number($('taskMaxClaims').value || 1),requirements:taskRequirementPayload()}) }); closeModal(); toast('Bonus task added'); await refreshAll(); } catch(error) { toast(error.message, true); } finally { $('taskButton').disabled = false; } }); }
`;
admin = admin.slice(0, addTaskStart) + addTaskReplacement + admin.slice(addTaskEnd);

const saveWheelStart = admin.indexOf('      async function saveWheel(event) {');
const saveWheelEnd = admin.indexOf('      async function saveReferralPolicy', saveWheelStart);
if (saveWheelStart < 0 || saveWheelEnd < 0) throw new Error('saveWheel block not found');
const saveWheelReplacement = `      async function persistWheel({ enabledOverride = null, quiet = false } = {}) { const segments = wheelSegmentsFromEditor(); if (segments.length !== 8) throw new Error('Wheel must have exactly 8 sectors'); if (segments.some(item => !item.label || !Number.isFinite(Number(item.rewardAmount)) || Number(item.rewardAmount) < 0 || !Number.isInteger(item.probabilityWeight) || item.probabilityWeight < 0)) throw new Error('Check the wheel prize fields'); const enabled = enabledOverride === null ? $('wheelEnabled').checked : enabledOverride; if (enabled && !segments.some(item => item.enabled && item.probabilityWeight > 0)) throw new Error('Enable at least one sector with chance weight above 0'); await api('/admin/wheel', { method:'PATCH', body:JSON.stringify({enabled,dailyClaimLimit:Number($('wheelLimit').value || 1),segments}) }); $('wheelForm').dataset.dirty = '0'; if (!quiet) toast('Wheel settings saved'); }
      async function saveWheel(event) { event.preventDefault(); const button = $('wheelButton'); button.disabled = true; try { await persistWheel(); await refreshAll(); } catch(error) { toast(error.message, true); } finally { button.disabled = false; } }
      async function quickToggleWheel() { const input = $('wheelEnabled'); const desired = input.checked; input.disabled = true; try { await persistWheel({ enabledOverride:desired, quiet:true }); toast(\`Wheel \${desired ? 'enabled' : 'disabled'}\`); await refreshAll(); } catch(error) { input.checked = !desired; toast(error.message, true); } finally { input.disabled = false; } }
      function equalizeWheelWeights() { document.querySelectorAll('[data-wheel-weight]').forEach(input => { input.value = '1'; }); $('wheelForm').dataset.dirty = '1'; toast('All wheel chance weights set equally. Save prizes to apply.'); }
`;
admin = admin.slice(0, saveWheelStart) + saveWheelReplacement + admin.slice(saveWheelEnd);

admin = replaceOnce(admin,
  `$('loginForm').addEventListener('submit', login); $('logoutButton').addEventListener('click', logout); $('refreshButton').addEventListener('click', () => refreshAll()); $('menuButton').addEventListener('click', () => $('sidebar').classList.toggle('open')); $('modalBackdrop').addEventListener('click', event => { if (event.target === $('modalBackdrop')) closeModal(); }); $('addAddressButton').addEventListener('click', () => addressForm()); $('ratesForm').addEventListener('submit', saveRates); $('rewardAdjustForm').addEventListener('submit', adjustReward); $('rewardPageForm').addEventListener('submit', saveRewardPage); $('campaignForm').addEventListener('submit', createCampaign); $('wheelForm').addEventListener('submit', saveWheel); $('referralPolicyForm').addEventListener('submit', saveReferralPolicy); $('broadcastForm').addEventListener('submit', broadcast);`,
  `$('loginForm').addEventListener('submit', login); $('logoutButton').addEventListener('click', logout); $('refreshButton').addEventListener('click', () => refreshAll()); $('menuButton').addEventListener('click', () => $('sidebar').classList.toggle('open')); $('modalBackdrop').addEventListener('click', event => { if (event.target === $('modalBackdrop')) closeModal(); }); $('addAddressButton').addEventListener('click', () => addressForm()); $('ratesForm').addEventListener('submit', saveRates); $('rewardAdjustForm').addEventListener('submit', adjustReward); $('rewardPageForm').addEventListener('submit', saveRewardPage); $('campaignForm').addEventListener('submit', createCampaign); $('wheelForm').addEventListener('submit', saveWheel); $('wheelEnabled').addEventListener('change', quickToggleWheel); $('wheelEqualWeights').addEventListener('click', equalizeWheelWeights); $('referralPolicyForm').addEventListener('submit', saveReferralPolicy); $('broadcastForm').addEventListener('submit', broadcast);`,
  'wheel quick actions listeners');

await writeFile('website/digirupee-admin.html', admin, 'utf8');

// ---------- App: prevent sign-in/register flash while restoring a valid session ----------
let app = await readFile('ui/digirupee-app.js', 'utf8');
app = replaceOnce(app,
  `    node.id = 'digiAuth';\n    node.className = 'digi-auth';`,
  `    node.id = 'digiAuth';\n    node.className = 'digi-auth';\n    node.hidden = true;`,
  'auth initially hidden');
app = replaceOnce(app,
  `  async function authenticated(result) {\n    state.user = result.user || null;`,
  `  async function authenticated(result) {\n    document.body.classList.add('digi-ready');\n    state.user = result.user || null;`,
  'authenticated ready state');
app = replaceOnce(app,
  `  document.addEventListener('DOMContentLoaded', async () => {\n    injectAuth();\n    const app = document.querySelector('.app'); if (app) app.style.display = 'none';\n    renderAuth('login');\n    setInterval(tick, 1000); tick();\n    try { const result = await api('/me', { allow401:true }); await authenticated(result); }\n    catch (error) { if (!String(error.message).includes('401')) renderAuth('login'); }\n  });`,
  `  document.addEventListener('DOMContentLoaded', async () => {\n    injectAuth();\n    const app = document.querySelector('.app'); if (app) app.style.display = 'none';\n    setInterval(tick, 1000); tick();\n    try {\n      const result = await api('/me', { allow401:true });\n      await authenticated(result);\n    } catch (error) {\n      document.body.classList.add('digi-ready');\n      const auth = $('digiAuth'); if (auth) auth.hidden = false;\n      const expectedAuthFailure = /401|auth|sign in|session/i.test(String(error.message || ''));\n      renderAuth('login', expectedAuthFailure ? '' : 'Could not restore your session. Please sign in.');\n    }\n  });`,
  'boot auth flow');
await writeFile('ui/digirupee-app.js', app, 'utf8');

// ---------- Generated HTML: hide legacy app markup before session restoration ----------
let prepare = await readFile('scripts/prepare-assets.mjs', 'utf8');
prepare = replaceOnce(prepare,
  `  html = html.replace(/<title>[\\s\\S]*?<\\/title>/i, '<title>digiRupee — Sell USDT</title>');`,
  `  html = html.replace(/<title>[\\s\\S]*?<\\/title>/i, '<title>digiRupee — Sell USDT</title>');\n  html = html.replace(/<\\/head>/i, '<style id="digi-boot-guard">body:not(.digi-ready) .app{visibility:hidden!important}body:not(.digi-ready)::before{content:"digiRupee";position:fixed;inset:0;z-index:999;display:grid;place-items:center;background:#050607;color:#f1cf67;font:800 22px system-ui,-apple-system,"Segoe UI",sans-serif;letter-spacing:-.02em}</style></head>');`,
  'boot guard injection');
await writeFile('scripts/prepare-assets.mjs', prepare, 'utf8');

console.log('Admin reward UX and auth boot flash patch applied');
